use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;
use crate::aap::caps::types::{AgentResponse, LlmError};

struct Node;

/// Instruction given to the model. The node holds `LLMClient<[lookup]>`, so the
/// only tool it can honour is `lookup` against the knowledge-base handle.
const SYSTEM: &str = "You are a customer support agent. Answer the user's question \
using the conversation intent and the knowledge provided. If you need more facts, \
request the `lookup` tool with a search query; otherwise reply with the answer text.";

/// Bound on the tool-orchestration loop so a model that keeps asking for tools
/// cannot spin forever.
const MAX_ROUNDS: usize = 4;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input, so no check here.
        let mut prompt = build_prompt(&ctx);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        append_lookup(&mut prompt, &req.query, &results);
                    } else {
                        // The only tool in this node's scope is `lookup`; anything
                        // else is outside its authority and is surfaced as an error.
                        return ResponseResult::Error(LlmError {
                            message: format!("unsupported tool requested: {}", req.tool),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge within the round budget"
                .to_string(),
        })
    }
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push('\n');

    p.push_str("\nKnowledge:\n");
    if ctx.knowledge.is_empty() {
        p.push_str("(none provided)\n");
    } else {
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }

    p.push_str("\nQuestion: ");
    p.push_str(&ctx.question);
    p
}

fn append_lookup(prompt: &mut String, query: &str, results: &[String]) {
    prompt.push_str("\n\n[tool:lookup query] ");
    prompt.push_str(query);
    prompt.push_str("\n[tool:lookup results]\n");
    if results.is_empty() {
        prompt.push_str("(no matches)\n");
    } else {
        for r in results {
            prompt.push_str("- ");
            prompt.push_str(r);
            prompt.push('\n');
        }
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
